    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Population: older children and adults who survived an episode of documented severe malnutrition in LMICs or famine exposure in childhood and adolescence (defined as 0-18 years of age). ... Outcomes: a range of cardiometabolic NCD outcomes ... measured at least 1 year after exposure ... All study designs were eligible.",
      "reason": "Eligibility criteria fully specify population, exposure definitions, comparators, outcomes, follow-up requirement (≥1 year), and eligible study designs."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "Human studies published in English were assessed for eligibility ... Grey literature and unpublished studies were excluded.",
      "reason": "Language restriction and publication status (peer-reviewed only) are specified, but no dissemination date/year restriction is reported."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "Data from studies of famine survivors and documented severe childhood malnutrition were analysed separately to account for the different nature of the exposures.",
      "reason": "Synthesis groups (famine exposure vs documented severe malnutrition, and narrative synthesis by outcome) are specified and linked to the exposure comparisons in the objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Although severe stunting is a form of severe malnutrition, we excluded studies that considered stunted children alone as the association between stunting and increased NCD risk has been described elsewhere.",
      "reason": "A rationale is provided for the notable restriction excluding stunting-only studies."
    }
  ],
  "confidence": 90
}

